// Baseline shelter the existing city already provides, independent of any
// housing the player builds. Citizens live across ALL districts, not only the
// residential ones, so this is the summed baseline population of every district
// scaled by an occupancy factor — leaving a modest, dystopian ~10% of the
// starting population without shelter. Counting only the housing/slums
// districts here understated capacity ~2x and pinned nearly the whole city as
// "homeless" no matter how much housing was built. The tick loop's HOUSING
// PRESSURE calc adds built housing supply on top.
export const RESIDENTIAL_DISTRICT_BASE_CAPACITY: number = Math.round(
  DISTRICT_TEMPLATES.reduce((sum, t) => sum + t.basePopulation, 0) * 0.87,
);

export function createDistricts(): District[] {
  return DISTRICT_TEMPLATES.map((t) => ({
    id: t.id,
    name: t.name,
    subtitle: t.subtitle,
    population: t.basePopulation,
    wealth: t.baseWealth,
    crime: t.baseCrime,
    unrest: t.baseUnrest,
    loyalty: t.baseLoyalty,
    infraQuality: t.baseInfra,
    gangInfluence: t.baseGang,
    mutationRate: t.baseMutation,
    defenseRating: t.baseDefense,
    industrialOutput: t.baseIndustrial,
    ecology: getBaseEcologyForCategory(t.category),
  }));
}

