// Task #217: per-tick hot path. The previous .find() walked all 271
// templates on every call, and several engine subsystems (faiths,
// wildlands ecology, district updates) call this once per district per
// tick — that's 271 × ~270 = ~73k linear scans per call site per tick.
// A static id→category Map makes the lookup O(1) and roughly halves
// the cost of the dominant per-tick subsystems.
const DISTRICT_CATEGORY_BY_ID: Map<string, string> = (() => {
  const m = new Map<string, string>();
  for (const d of DISTRICT_TEMPLATES) m.set(d.id, d.category);
  return m;
})();

export function getDistrictCategory(id: string): string {
  return DISTRICT_CATEGORY_BY_ID.get(id) ?? "unknown";
}
